import json
import re
import sys

import framework_evidence


def emit(label, value):
    print(json.dumps({"stage": label, "result": value}, ensure_ascii=False))


def stdout_values(value):
    """Collect raw stdout fields from the helper's returned evidence envelope."""
    found = []
    if isinstance(value, dict):
        for key, item in value.items():
            if key == "stdout" and isinstance(item, str):
                found.append(item)
            else:
                found.extend(stdout_values(item))
    elif isinstance(value, list):
        for item in value:
            found.extend(stdout_values(item))
    return found


def main():
    search_argv = [
        "msfconsole", "-q", "-x",
        "search jenkins; search CVE-2024-23897; exit"
    ]
    try:
        search_result = framework_evidence.run_tool(search_argv)
    except Exception as exc:
        emit("search_error", {"command": search_argv, "error": repr(exc)})
        return 1

    emit("metasploit_search", search_result)
    module_pattern = re.compile(
        r"(?<![A-Za-z0-9_./-])((?:exploit|auxiliary|post|encoder|payload|evasion)/[A-Za-z0-9_./-]+)"
    )
    candidates = []
    seen = set()
    for text in stdout_values(search_result):
        for line in text.splitlines():
            for match in module_pattern.findall(line):
                module = match.rstrip(".,;:)")
                if module not in seen:
                    seen.add(module)
                    candidates.append(module)

    emit("search_candidates", {
        "modules": candidates,
        "note": "Names were extracted from raw search stdout; this is not an applicability assessment."
    })
    if not candidates:
        emit("metadata_inspection", {
            "status": "not_run",
            "reason": "No module paths were extracted from captured search stdout; results may be empty, formatted differently, or incomplete."
        })
        return 0

    info_commands = "; ".join("info " + name for name in candidates) + "; exit"
    info_argv = ["msfconsole", "-q", "-x", info_commands]
    try:
        info_result = framework_evidence.run_tool(info_argv)
    except Exception as exc:
        emit("metadata_inspection_error", {"command": info_argv, "error": repr(exc)})
        return 1
    emit("metadata_inspection", info_result)
    return 0


if __name__ == "__main__":
    sys.exit(main())

