import json
import re
import sys

try:
    from framework_evidence import run_tool
except Exception as exc:
    print(json.dumps({"error": "Could not import the supplied framework_evidence helper", "detail": str(exc)}))
    sys.exit(1)


def as_text(value):
    if isinstance(value, str):
        return value
    if isinstance(value, dict):
        return "\n".join(str(value.get(k, "")) for k in ("stdout", "stderr"))
    return ""


def call_console(label, commands):
    argv = ["msfconsole", "-q", "-x", commands + "; exit"]
    try:
        envelope = run_tool(argv)
    except Exception as exc:
        envelope = {"command": argv, "call_error": str(exc)}
    print(json.dumps({"section": label, "tool_envelope": envelope}, ensure_ascii=False))
    return envelope


def tool_text(envelope):
    if isinstance(envelope, dict):
        return "\n".join(str(envelope.get(k, "")) for k in ("stdout", "stderr"))
    return str(envelope)


# Jenkins 2.441 is the observed fingerprint. These CVE searches target the
# Jenkins security issues associated with that release line; raw output is
# retained so applicability is not inferred from identifiers alone.
search_commands = [
    ("jenkins", "search jenkins"),
    ("CVE-2024-23897", "search cve:2024-23897"),
    ("CVE-2024-23898", "search cve:2024-23898"),
]
search_results = []
for label, command in search_commands:
    envelope = call_console("search:" + label, command)
    search_results.append((label, envelope))

# Collect module paths from search output. For CVE searches, only inspect paths
# explicitly Jenkins-related; the general Jenkins search is itself the scope.
module_re = re.compile(r"\b(?:exploit|auxiliary|post)/[A-Za-z0-9_./-]+")
candidates = {}
for label, envelope in search_results:
    text = tool_text(envelope)
    for line in text.splitlines():
        paths = module_re.findall(line)
        if not paths:
            continue
        for path in paths:
            path = path.rstrip(".,:;)")
            if label == "jenkins" or "jenkins" in line.lower() or "jenkins" in path.lower():
                candidates.setdefault(path, []).append({"search": label, "result_line": line})

print(json.dumps({
    "section": "candidate_selection",
    "observed_fingerprint": "Jenkins 2.441 (supplied prior observation)",
    "selection_rule": "Module paths found in the Jenkins search, plus paths explicitly identified as Jenkins-related in either CVE search; this is a search-output filter, not an applicability conclusion.",
    "candidates": [{"module": path, "source_lines": sources} for path, sources in candidates.items()],
    "candidate_count": len(candidates)
}, ensure_ascii=False))

if candidates:
    info_commands = "; ".join("info " + path for path in candidates)
    call_console("candidate_module_metadata", info_commands)
else:
    print(json.dumps({
        "section": "candidate_module_metadata",
        "status": "not_run",
        "reason": "No Jenkins-related module path was extracted from the captured search output. Inspect the raw search envelopes and their status before drawing conclusions."
    }))

