    for line in output.splitlines():
        paths = pattern.findall(line)
        if not paths:
            continue
        lowered = line.lower()
        for path in paths:
            if "jenkins" in path.lower() or "jenkins" in lowered:
                if path not in found:
                    found.append(path.rstrip(".,;:"))
    return found


