            "command": info_argv,
            "candidate_paths_requested": paths,
            "envelope": info_result
        }
    except Exception as exc:
        result["metadata_inspection"] = {
            "status": "invocation_error",
            "command": info_argv,
            "candidate_paths_requested": paths,
            "error": str(exc)
        }

