import json
import re
import sys

try:
    import framework_evidence
except Exception as exc:
    print(json.dumps({"stage": "helper_import", "error": repr(exc)}))
    raise SystemExit(1)


def as_object(value):
    if isinstance(value, dict):
        return value
    if isinstance(value, str):
        try:
            parsed = json.loads(value)
            if isinstance(parsed, dict):
                return parsed
        except Exception:
            pass
    return {}


def collect_strings(value, key="stdout"):
    found = []
    if isinstance(value, dict):
        for k, v in value.items():
            if k == key and isinstance(v, str):
                found.append(v)
            else:
                found.extend(collect_strings(v, key))
    elif isinstance(value, list):
        for item in value:
            found.extend(collect_strings(item, key))
    return found


def emit_envelope(stage, result):
    # Keep the helper's complete envelope, including raw streams and parser status.
    if isinstance(result, str):
        try:
            obj = json.loads(result)
            if isinstance(obj, dict):
                result = obj
        except Exception:
            pass
    print(json.dumps({"stage": stage, "envelope": result}, ensure_ascii=False))


try:
    search_result = framework_evidence.run_tool(["msfconsole", "-q", "-x", "search jenkins"])
except Exception as exc:
    print(json.dumps({"stage": "search", "error": repr(exc)}))
    raise SystemExit(1)

emit_envelope("jenkins_search", search_result)
search_obj = as_object(search_result)
search_text = "\n".join(collect_strings(search_obj))
if not search_text and isinstance(search_result, str):
    search_text = search_result

# Extract only module-path-shaped tokens containing Jenkins from actual search output.
module_pattern = re.compile(r"(?<![A-Za-z0-9_./-])(?:exploit|auxiliary|post|encoder|payload|nop|evasion)/[A-Za-z0-9_./-]*jenkins[A-Za-z0-9_./-]*", re.IGNORECASE)
modules = sorted(set(match.group(0).rstrip(".,:;)") for match in module_pattern.finditer(search_text)), key=str.lower)

if not modules:
    print(json.dumps({
        "stage": "metadata_requests",
        "status": "not_attempted",
        "reason": "No Jenkins module identifiers could be extracted from the captured search output; this is not evidence that no matching modules exist.",
        "search_output_available": bool(search_text)
    }))
    raise SystemExit(0)

# Request detailed metadata for every Jenkins module identifier actually returned by search.
commands = ["info " + module for module in modules]
commands.append("exit -y")
try:
    info_result = framework_evidence.run_tool(["msfconsole", "-q", "-x", "; ".join(commands)])
    emit_envelope("candidate_module_info", info_result)
except Exception as exc:
    print(json.dumps({
        "stage": "candidate_module_info",
        "error": repr(exc),
        "requested_module_ids": modules
    }, ensure_ascii=False))
    raise SystemExit(1)

