import sys


def emit(value):
    print(json.dumps(value, ensure_ascii=False, sort_keys=True))


def main():
    try:
        from framework_evidence import run_tool
    except Exception as exc:
        emit({"status": "helper_import_failed", "error": repr(exc)})
        return 1

    # These focused console searches obtain identifiers from live Metasploit output;
    # no module is selected for execution.
    search_commands = [
        "search jenkins xstream",
        "search jenkins credential",
        "search jenkins cli",
        "exit",
    ]
    search_argv = ["msfconsole", "-q", "-x", "; ".join(search_commands)]
    try:
        search_result = run_tool(search_argv)
    except Exception as exc:
        emit({"stage": "metasploit_search", "command": search_argv, "error": repr(exc)})
        return 1

    emit({"stage": "metasploit_search", "result": search_result})
    try:
        search_text = "\n".join(
            str(search_result.get(key, ""))
