    info_argv = ["msfconsole", "-q", "-x", "; ".join(info_commands)]
    try:
        info_result = run_tool(info_argv)
        emit({
            "stage": "individual_metadata",
            "requested_identifiers": candidates,
            "result": info_result,
            "note": "This retains Metasploit's actual response; individual response completeness and applicability must be assessed from that output.",
        })
    except Exception as exc:
        emit({
            "stage": "individual_metadata",
            "requested_identifiers": candidates,
            "command": info_argv,
            "error": repr(exc),
        })
    return 0


