import json
import re
import sys

try:
    import framework_evidence
except Exception as exc:
    print(json.dumps({"status": "helper_import_error", "error": str(exc)}, ensure_ascii=False))
    raise SystemExit(1)


def run(argv):
    try:
        return framework_evidence.run_tool(argv)
    except Exception as exc:
        return {"command": argv, "status": "wrapper_error", "error": str(exc)}


def text_from_envelope(value):
    """Extract output for discovery while retaining the untouched envelope elsewhere."""
    if isinstance(value, dict):
        for key in ("stdout", "output"):
            item = value.get(key)
            if isinstance(item, str):
                return item
            if isinstance(item, dict):
                nested = text_from_envelope(item)
                if nested:
                    return nested
        for key in ("tool_runs", "results"):
            items = value.get(key)
            if isinstance(items, list):
                return "\n".join(text_from_envelope(item) for item in items)
    elif isinstance(value, list):
        return "\n".join(text_from_envelope(item) for item in value)
    return ""


search_argv = ["msfconsole", "-q", "-x", "search jenkins; exit"]
search_envelope = run(search_argv)
search_text = text_from_envelope(search_envelope)

# Metasploit search tables include module paths. Only issue info commands for
# identifiers returned by the console; this avoids guessing module names.
module_pattern = re.compile(r"\b(?:exploit|auxiliary|post|encoder|payload|evasion)/[A-Za-z0-9_./-]+")
modules = sorted(set(module_pattern.findall(search_text)))
jenkins_modules = [name for name in modules if "jenkins" in name.lower()]

info_envelope = None
info_argv = None
if jenkins_modules:
