import json
import re
import sys

TARGET = "192.168.5.1"


def raw_stdout(value):
    """Find a tool envelope's raw stdout without discarding the envelope."""
    if isinstance(value, dict):
        if isinstance(value.get("stdout"), str):
            return value["stdout"]
        for child in value.values():
            found = raw_stdout(child)
            if found is not None:
                return found
    elif isinstance(value, list):
        for child in value:
            found = raw_stdout(child)
            if found is not None:
                return found
    elif isinstance(value, str):
        try:
            return raw_stdout(json.loads(value))
        except (ValueError, TypeError):
            return None
    return None


def print_envelope(stage, envelope):
    # Keep the evidence-helper return value intact, including raw streams and
    # structured observations, while labeling which operation produced it.
    print(json.dumps({"stage": stage, "result": envelope}, ensure_ascii=False))


def main():
    try:
        from framework_evidence import run_tool
    except Exception as exc:
        print(json.dumps({"stage": "setup", "status": "error",
                          "error": "Could not import supplied framework_evidence helper: " + str(exc)}))
        return 2

    scan_argv = ["nmap", "-sV", "-p-", "--open", "-T3", TARGET]
    try:
        scan = run_tool(scan_argv)
    except Exception as exc:
        print(json.dumps({"stage": "service_discovery", "command": scan_argv,
                          "status": "error", "error": str(exc)}))
        return 1
    print_envelope("service_discovery", scan)

    text = raw_stdout(scan) or ""
    # Parse only Nmap's observed open TCP service rows. HTTP requests below are
    # restricted to ports whose observed service/version identifies HTTP(S).
    endpoints = {}
    for line in text.splitlines():
        match = re.match(r"^\s*(\d+)/tcp\s+open\s+(\S+)(?:\s+(.*))?$", line)
        if not match:
            continue
        port = int(match.group(1))
        service = match.group(2).lower()
        details = match.group(3) or ""
        is_http = ("http" in service or "https" in service or
                   "jenkins" in details.lower() or
                   ("ssl" in service and "http" in details.lower()))
        if is_http:
            secure = ("https" in service or "ssl" in service or
                      port in (443, 8443) or "https" in details.lower())
            endpoints[port] = "https" if secure else "http"

    if not endpoints:
        print(json.dumps({
            "stage": "http_endpoint_selection",
            "target": TARGET,
            "status": "no_http_endpoint_identified_from_scan_output",
            "note": "This means no HTTP(S) TCP service row was parsed from available scan stdout; it does not establish that no endpoint exists. Check scan status, structured output, and coverage in the retained envelope."
        }))
        return 0

    for port, scheme in sorted(endpoints.items()):
        url = f"{scheme}://{TARGET}:{port}/"
        argv = ["curl", "-sS", "-i", "-L", "--max-redirs", "5",
                "--max-time", "15", "-k", "-w",
                "\\n__ENDPOINT_METADATA__ effective_url=%{url_effective} http_code=%{http_code}\\n",
                url]
        try:
            response = run_tool(argv)
            print_envelope("http_root_request", response)
        except Exception as exc:
            print(json.dumps({"stage": "http_root_request", "command": argv,
                              "status": "error", "error": str(exc)}))

    return 0


if __name__ == "__main__":
    sys.exit(main())

