import json
import re
import sys
import urllib.error
import urllib.request

TARGET = "192.168.5.1"
PORTS = (80, 443, 8080, 50000)


def walk(value):
    if isinstance(value, dict):
        yield value
        for child in value.values():
            yield from walk(child)
    elif isinstance(value, list):
        for child in value:
            yield from walk(child)


def get_tool_runs(envelope):
    if isinstance(envelope, dict):
        runs = envelope.get("tool_runs")
        if isinstance(runs, list):
            return runs
        for value in envelope.values():
            found = get_tool_runs(value)
            if found:
                return found
    elif isinstance(envelope, list):
        for value in envelope:
            found = get_tool_runs(value)
            if found:
                return found
    return []


def open_ports(envelope):
    found = {}
    for run in get_tool_runs(envelope):
        structured = run.get("structured_output")
        for item in walk(structured):
            state = str(item.get("state", "")).lower()
            port = item.get("port")
            if state == "open" and port is not None:
                try:
                    number = int(port)
                except (TypeError, ValueError):
                    continue
                service = item.get("service", {})
                if isinstance(service, dict):
                    name = service.get("name", "")
                else:
                    name = str(service or item.get("name", ""))
                found[number] = str(name)
        text = run.get("stdout", "")
        if isinstance(text, str):
            for match in re.finditer(r"(?m)^\s*(\d+)/tcp\s+open\s+(\S+)", text):
                found.setdefault(int(match.group(1)), match.group(2))
    return found


def request_endpoint(port, scheme, path="/"):
    url = f"{scheme}://{TARGET}:{port}{path}"
    request = urllib.request.Request(url, headers={"User-Agent": "endpoint-observation/1.0"})
    opener = urllib.request.build_opener(urllib.request.HTTPHandler())
    if scheme == "https":
        opener = urllib.request.build_opener(urllib.request.HTTPSHandler())
    try:
        response = opener.open(request, timeout=5)
        try:
            body = response.read(8192)
            headers = dict(response.headers.items())
            return {
                "requested_url": url,
                "status": response.status,
                "final_url": response.geturl(),
                "headers": headers,
                "jenkins_headers": {
                    key: value for key, value in headers.items()
                    if key.lower().startswith("x-jenkins") or key.lower() in ("server", "location")
                },
                "body_excerpt": body.decode("utf-8", errors="replace")[:1500],
                "body_bytes_read": len(body),
                "truncated_at_8192_bytes": len(body) == 8192,
            }
        finally:
            response.close()
    except urllib.error.HTTPError as exc:
        try:
            body = exc.read(8192)
        except Exception:
            body = b""
        headers = dict(exc.headers.items()) if exc.headers else {}
        return {
            "requested_url": url,
            "status": exc.code,
            "final_url": exc.geturl(),
            "headers": headers,
            "jenkins_headers": {
                key: value for key, value in headers.items()
                if key.lower().startswith("x-jenkins") or key.lower() in ("server", "location")
            },
            "body_excerpt": body.decode("utf-8", errors="replace")[:1500],
            "response_error": str(exc),
        }
    except Exception as exc:
        return {"requested_url": url, "response": "failed_or_absent", "error": repr(exc)}


def main():
    try:
        from framework_evidence import run_tool
    except Exception as exc:
        print(json.dumps({"stage": "tool_setup", "status": "failed", "error": repr(exc)}))
        return 2

    command = [
        "nmap", "-Pn", "-n", "-sT", "-sV", "--version-light",
        "--host-timeout", "45s", "-p", ",".join(map(str, PORTS)), TARGET,
    ]
    try:
        envelope = run_tool(command)
    except Exception as exc:
        print(json.dumps({"stage": "service_discovery", "command": command,
                          "status": "tool_call_failed", "error": repr(exc)}))
        return 1

    print(json.dumps({"stage": "service_discovery", "evidence_envelope": envelope},
                     ensure_ascii=False, default=str))
    ports = open_ports(envelope)
    http_observations = []
    for port, service in sorted(ports.items()):
        service_lower = service.lower()
        if port not in (80, 443, 8080) and "http" not in service_lower:
            continue
        scheme = "https" if port == 443 or "https" in service_lower else "http"
        http_observations.append({
            "port": port,
            "service_label": service,
            "root_request": request_endpoint(port, scheme, "/"),
        })

    runs = get_tool_runs(envelope)
    run_states = [{"status": run.get("status"), "exit_code": run.get("exit_code"),
                   "stderr": run.get("stderr", "")} for run in runs]
    print(json.dumps({
        "stage": "http_endpoint_inspection",
        "target": TARGET,
        "discovery_run_status": run_states,
        "parsed_open_ports": ports,
        "http_observations": http_observations,
        "interpretation_note": "No HTTP response is not proof of service absence; inspect scan status and raw evidence envelope. Context path is reported only when indicated by observed URL or response headers.",
    }, ensure_ascii=False, default=str))
    return 0


if __name__ == "__main__":
    sys.exit(main())

